pub open spec fn is_causally_ready_spec(
    msg_clock: Seq<u64>, local_clock: Seq<u64>, sender: int,
) -> bool
    recommends
        msg_clock.len() == local_clock.len(),
        0 <= sender < msg_clock.len() as int,
{
