    requires a.len() == b.len()
    ensures result == happens_before_spec(a@, b@)
{
    let mut all_leq: bool = true;
    let mut some_lt: bool = false;
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            a.len() == b.len(),
            all_leq == (forall|j: int| 0 <= j < i as int ==> a@[j] <= b@[j]),
            some_lt == (exists|j: int| 0 <= j < i as int && a@[j] < b@[j]),
        decreases a.len() - i,
